`default_nettype none
`include "defines.sv"

// free input variables, can take any value each cycle as long as the `assume` are satisfied
module testbench (
	input check,
	input clock, reset
);
	`RVFI_WIRES
	`RVFI_BUS_WIRES

	`RISCV_FORMAL_CHECKER checker_inst (
		.clock  (clock),
		.reset  (reset),
		.check   (check),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

	// Ignore rvfi_order loopback, otherwise the check might be invalid.
	reg rvfi_order_loopback;
	always @(posedge clock) begin
		if (reset) begin
			rvfi_order_loopback <= 0;
		end else if (rvfi_valid && rvfi_order == {64{1'b1}}) begin
			rvfi_order_loopback <= 1;
		end
	end
	always_comb assume (!(rvfi_order_loopback && check));

	rvfi_wrapper wrapper (
		.clock (clock),
		.reset (reset),
		`RVFI_CONN
		`RVFI_BUS_CONN
	);

/// Helper Assertion Begin

	// Architectural GPR shadow model driven by RVFI.
	// This constrains the proof to reachable states where register read data is
	// consistent with the prior RVFI write stream.
	reg [`RISCV_FORMAL_XLEN-1:0] h_gpr [0:31];

	wire h_rvfi_valid = rvfi_valid[0];
	wire h_rvfi_trap  = rvfi_trap[0];

	wire [4:0] h_rs1_addr = rvfi_rs1_addr[0*5 +: 5];
	wire [4:0] h_rs2_addr = rvfi_rs2_addr[0*5 +: 5];
	wire [`RISCV_FORMAL_XLEN-1:0] h_rs1_rdata = rvfi_rs1_rdata[0*`RISCV_FORMAL_XLEN +: `RISCV_FORMAL_XLEN];
	wire [`RISCV_FORMAL_XLEN-1:0] h_rs2_rdata = rvfi_rs2_rdata[0*`RISCV_FORMAL_XLEN +: `RISCV_FORMAL_XLEN];

	wire [4:0] h_rd_addr = rvfi_rd_addr[0*5 +: 5];
	wire [`RISCV_FORMAL_XLEN-1:0] h_rd_wdata = rvfi_rd_wdata[0*`RISCV_FORMAL_XLEN +: `RISCV_FORMAL_XLEN];

	integer h_i;
	always @(posedge clock) begin
		if (reset) begin
			for (h_i = 0; h_i < 32; h_i = h_i + 1)
				h_gpr[h_i] <= '0;
		end else begin
			// x0 is always 0.
			h_gpr[0] <= '0;

			if (h_rvfi_valid) begin
				// Reads reflect current architectural state (even for trapping instructions).
				if (h_rs1_addr == 0)
					h_rs1_x0: assert(h_rs1_rdata == '0);
				else
					h_rs1_shadow: assert(h_rs1_rdata == h_gpr[h_rs1_addr]);

				if (h_rs2_addr == 0)
					h_rs2_x0: assert(h_rs2_rdata == '0);
				else
					h_rs2_shadow: assert(h_rs2_rdata == h_gpr[h_rs2_addr]);

				// Commit writes only for non-trapping instructions; ignore writes to x0.
				if (!h_rvfi_trap && (h_rd_addr != 0)) begin
					h_gpr[h_rd_addr] <= h_rd_wdata;
				end
			end
		end
	end

/// Helper Assertion End
endmodule

